This Dijkstra code has a bug in the relaxation step. Find and fix it: 

import heapq
def dijkstra(graph, start):
    dist = {n: float('inf') for n in graph}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        for v, weight in graph[u].items():
            if dist[u] + weight > dist[v]: # BUG HERE
                dist[v] = dist[u] + weight
                heapq.heappush(pq, (dist[v], v))
    return dist
